  ('56ac4955-ba24-4dec-92c9-1c59ee0cf05d'::uuid, 3, 'The chart shows the number of visitors to a park over four days. By what percentage did visitor numbers increase from Thursday to Saturday?', 'يوضّح المخطط عدد زوار حديقة على مدى أربعة أيام. بأي نسبة مئوية زاد عدد الزوار من الخميس إلى السبت؟', NULL, '["50%", "80%", "90%", "125%"]'::jsonb, '{"kind":"data","style":"bar","title_en":"Visitors","title_ar":"عدد الزوار","label_head_en":"Day","label_head_ar":"اليوم","rows":[{"label_en":"Thursday","label_ar":"الخميس","value":40},{"label_en":"Friday","label_ar":"الجمعة","value":60},{"label_en":"Saturday","label_ar":"السبت","value":90},{"label_en":"Sunday","label_ar":"الأحد","value":50}],"replaces":"56ac4955-ba24-4dec-92c9-1c59ee0cf05d"}'::jsonb),
  ('043892e7-550d-412c-ae35-abe0e5a12ade'::uuid, 1, 'The table shows the length of four trails. A hiker walks Trails A, C and D. What is the total distance walked?', 'يوضّح الجدول طول أربعة مسارات. يمشي متنزّه المسارات أ وج ود. ما المسافة الإجمالية المقطوعة؟', NULL, '["10.5 km", "11.8 km", "12.0 km", "16.0 km"]'::jsonb, '{"kind":"data","style":"table","title_en":"Length (km)","title_ar":"الطول (كم)","label_head_en":"Trail","label_head_ar":"المسار","rows":[{"label_en":"Trail A","label_ar":"المسار أ","value":3.5},{"label_en":"Trail B","label_ar":"المسار ب","value":4.2},{"label_en":"Trail C","label_ar":"المسار ج","value":2.8},{"label_en":"Trail D","label_ar":"المسار د","value":5.5}],"replaces":"043892e7-550d-412c-ae35-abe0e5a12ade"}'::jsonb),
  ('a6129471-076a-4d64-9b9c-424c5ab93fc3'::uuid, 1, 'The chart shows the number of cars entering a car park each hour. Which two hours had the same number of cars entering?', 'يوضّح المخطط عدد السيارات الداخلة إلى موقف السيارات كل ساعة. في أي ساعتين دخل العدد نفسه من السيارات؟', NULL, '["9 a.m. and 10 a.m.", "9 a.m. and 11 a.m.", "10 a.m. and 12 p.m.", "11 a.m. and 12 p.m."]'::jsonb, '{"kind":"data","style":"bar","title_en":"Cars entering","title_ar":"السيارات الداخلة","label_head_en":"Hour","label_head_ar":"الساعة","rows":[{"label_en":"9 a.m.","label_ar":"9 صباحاً","value":12},{"label_en":"10 a.m.","label_ar":"10 صباحاً","value":15},{"label_en":"11 a.m.","label_ar":"11 صباحاً","value":12},{"label_en":"12 p.m.","label_ar":"12 ظهراً","value":9}],"replaces":"a6129471-076a-4d64-9b9c-424c5ab93fc3"}'::jsonb),
  ('3c06a743-d58c-449c-a5a3-678b4ffc28b0'::uuid, 1, 'The table shows the number of items collected in each colour. Red and green together make up what fraction of all items collected?', 'يوضّح الجدول عدد العناصر المجمّعة من كل لون. ما الكسر الذي يشكّله الأحمر والأخضر معاً من إجمالي العناصر المجمّعة؟', NULL, '["8/25", "16/25", "13/25", "1/2"]'::jsonb, '{"kind":"data","style":"table","title_en":"Items collected","title_ar":"عدد العناصر المجمّعة","label_head_en":"Colour","label_head_ar":"اللون","rows":[{"label_en":"Red","label_ar":"أحمر","value":8},{"label_en":"Blue","label_ar":"أزرق","value":5},{"label_en":"Green","label_ar":"أخضر","value":8},{"label_en":"Yellow","label_ar":"أصفر","value":4}],"replaces":"3c06a743-d58c-449c-a5a3-678b4ffc28b0"}'::jsonb),
  ('4f4c1ee7-03db-4f94-b8f2-2ca071e2eeb7'::uuid, 1, 'The chart shows the distance walked each day. How much farther was walked on Thursday than on Monday?', 'يوضّح المخطط المسافة المقطوعة مشياً كل يوم. كم كانت المسافة المقطوعة يوم الخميس أكثر منها يوم الاثنين؟', NULL, '["3 km", "4 km", "8 km", "12 km"]'::jsonb, '{"kind":"data","style":"bar","title_en":"Distance walked (km)","title_ar":"المسافة المقطوعة (كم)","label_head_en":"Day","label_head_ar":"اليوم","rows":[{"label_en":"Monday","label_ar":"الاثنين","value":4},{"label_en":"Tuesday","label_ar":"الثلاثاء","value":7},{"label_en":"Wednesday","label_ar":"الأربعاء","value":5},{"label_en":"Thursday","label_ar":"الخميس","value":8}],"replaces":"4f4c1ee7-03db-4f94-b8f2-2ca071e2eeb7"}'::jsonb),
  ('6f9ecd18-b72d-412d-9a83-b21f9e28fced'::uuid, 1, 'The table shows the cups of water drunk each day. What is the average number of cups per day over these three days?', 'يوضّح الجدول عدد أكواب الماء المشروبة كل يوم. ما متوسط عدد الأكواب يومياً خلال هذه الأيام الثلاثة؟', NULL, '["6", "7", "8", "21"]'::jsonb, '{"kind":"data","style":"table","title_en":"Cups of water","title_ar":"عدد الأكواب","label_head_en":"Day","label_head_ar":"اليوم","rows":[{"label_en":"Sunday","label_ar":"الأحد","value":6},{"label_en":"Monday","label_ar":"الاثنين","value":8},{"label_en":"Tuesday","label_ar":"الثلاثاء","value":7}],"replaces":"6f9ecd18-b72d-412d-9a83-b21f9e28fced"}'::jsonb),
  ('667bd222-2b8e-4348-8cfb-84ba4edaad60'::uuid, 2, 'Look at the four shapes. Which shape does NOT belong with the others?', 'انظر إلى الأشكال الأربعة. أيّ شكل لا ينتمي إلى البقية؟', 'A square, a rectangle and a diamond each have four sides; the triangle has three, so it is the odd one out. Other features split the set evenly (square and diamond have equal sides, rectangle and triangle do not; square and rectangle have right angles, diamond and triangle do not), so only the number of sides singles out one shape.', '["A square", "A rectangle", "A triangle", "A four-sided diamond"]'::jsonb, '{"kind":"options","options":[{"shape":"square"},{"shape":"rectangle"},{"shape":"isosceles"},{"shape":"diamond"}],"replaces":"667bd222-2b8e-4348-8cfb-84ba4edaad60"}'::jsonb);

DO $$
BEGIN
  IF (SELECT count(*) FROM psy_items p JOIN fig_load d ON d.replaces = p.id
      WHERE p.status = 'in_review' AND p.figure IS NULL AND p.options_en = d.options_en) <> 21 THEN
    RAISE EXCEPTION 'expected 21 in_review text originals with unchanged option text';
  END IF;
  IF EXISTS (SELECT 1 FROM psy_items WHERE source = 'figure_v1') THEN
    RAISE EXCEPTION 'figure_v1 items already loaded';
  END IF;
END $$;

INSERT INTO psy_items (scale_id, kind, stem_en, stem_ar, options_en, options_ar, correct_index, reverse_keyed,
                       difficulty, status, source, facet, rationale, ar_reviewed, figure)
SELECT o.scale_id, o.kind, d.stem_en, d.stem_ar, o.options_en, o.options_ar, d.correct, o.reverse_keyed,
       o.difficulty, 'in_review', 'figure_v1', o.facet, coalesce(d.rationale, o.rationale), false, d.figure
FROM fig_load d JOIN psy_items o ON o.id = d.replaces;

UPDATE psy_items SET status = 'retired' WHERE id IN (SELECT replaces FROM fig_load);

DO $$
BEGIN
  IF (SELECT count(*) FROM psy_items WHERE source = 'figure_v1' AND status = 'in_review' AND figure IS NOT NULL) <> 21 THEN
    RAISE EXCEPTION 'insert count mismatch';
  END IF;
  IF EXISTS (SELECT 1 FROM psy_items p JOIN fig_load d ON d.replaces = p.id WHERE p.status <> 'retired') THEN
    RAISE EXCEPTION 'a replaced text item is still servable';
  END IF;
  IF (SELECT count(*) FROM psy_items WHERE facet IN ('ind_matrix', 'num_data') AND status IN ('approved', 'in_review') AND figure IS NULL) <> 0 THEN
    RAISE EXCEPTION 'a text matrix or data item is still servable';
  END IF;
END $$;

COMMIT;
